def count_ways(n, k):
    MOD = 10**9 + 7

    # Helper function to compute x^y % p using binary exponentiation
    def power(x, y, p):
        res = 1
        x = x % p
        while y > 0:
            if (y & 1) == 1:
                res = (res * x) % p
            y = y >> 1
            x = (x * x) % p
        return res

    # Helper function to compute factorial % p
    def factorial(num, p):
        result = 1
        for i in range(2, num + 1):
            result = (result * i) % p
        return result

    # Helper function to compute modular inverse using Fermat's Little Theorem
    def mod_inverse(num, p):
        return power(num, p - 2, p)

    # Helper function to compute nCr % p
    def nCr(n, r, p):
        if r > n:
            return 0
        numerator = factorial(n, p)
        denominator = (factorial(r, p) * factorial(n - r, p)) % p
        return (numerator * mod_inverse(denominator, p)) % p

    # Calculate the number of ways to distribute k-1 distinct values
    # across n rows and n columns, with each row and column having at least one of these values
    def count_distributions(n, k):
        if k < n:
            return 0
        # Total ways to choose k-1 distinct values from k
        total_ways = nCr(k, n - 1, MOD)
        # Subtract invalid configurations where some rows or columns have no value
        invalid_configurations = 0
        for i in range(n):
            invalid_configurations += nCr(k - 1, n - 2, MOD) * nCr(n - 1, i, MOD) * nCr(n - 1, n - 1 - i, MOD)
            invalid_configurations %= MOD
        return (total_ways - invalid_configurations + MOD) % MOD

    return count_distributions(n, k)

